// This script standardizes input data and selects the WA ID as the permanent key.

let message = "";
let sessionId = "";
let metadata = {};
const item = items[0].json;

// 1. Source: WhatsApp (has contacts array)
if (item.contacts && item.contacts[0] && item.messages) {
  message = item.messages[0].text.body;
  sessionId = item.contacts[0].wa_id; 
}

// 2. Source: App Webhook (Data is usually inside 'body')
else if (item.body && item.body.message && item.body.sessionId) {
  message = item.body.message;
  sessionId = item.body.sessionId;
  metadata = item.body.metadata || {};
}

// 3. Source: App Webhook (Fallback - Data might be at top level depending on settings)
else if (item.message && item.sessionId) {
  message = item.message;
  sessionId = item.sessionId;
  metadata = item.metadata || {};
}

// validation to prevent memory crash
if (!sessionId) {
  sessionId = "unknown_user"; // Fallback to prevent crash
}

// Build user context from metadata
let userContext = "";
if (metadata.userName) {
  userContext += "User name: " + metadata.userName + ". ";
}
if (metadata.dob) {
  userContext += "Date of birth: " + metadata.dob + ". ";
}
if (metadata.pob) {
  userContext += "Place of birth: " + metadata.pob + ". ";
}
if (metadata.tob) {
  userContext += "Time of birth: " + metadata.tob + ". ";
}
if (metadata.currentLocation) {
  userContext += "Current location: " + metadata.currentLocation + ". ";
}
if (metadata.isSystemContext) {
  userContext +=
    "[This is a system greeting request, not a user question] ";
}

// Prepend user context to message if available
const fullMessage = userContext ? "[USER INFO: " + userContext.trim() + "] " + message : message;

return [{ json: { message: fullMessage, sessionId: sessionId, source: (item.contacts ? "WHATSAPP" : "APP"), metadata: metadata } }];

/* Compute Age and normalize metadata (with debug logs) */
const item = items[0].json;
const metadata = item.metadata || item.body?.metadata || {};

// Debug incoming metadata
console.log('Compute Age node - incoming metadata:', JSON.stringify(metadata));

const canonical = {
  userName: metadata.userName || metadata.user_name || metadata.name || null,
  dob: metadata.dateOfBirth || metadata.dob || metadata.DOB || null,
  tob: metadata.timeOfBirth || metadata.tob || metadata.time || null,
  pob: metadata.placeOfBirth || metadata.pob || metadata.place || null,
  currentLocation: metadata.currentLocation || metadata.location || null,
  isSystemContext: (metadata.isSystemContext === true || metadata.isSystemContext === 'true') || false
};

console.log('Compute Age node - canonical metadata:', JSON.stringify(canonical));

// Helper to compute age (years) and log parse details
function computeAge(dobString) {
  if (!dobString) {
    console.log('Compute Age node - no DOB provided');
    return null;
  }

  // Try Date parsing; prefer ISO (YYYY-MM-DD). Best-effort fallback to Date.parse.
  let d = new Date(dobString);
  if (isNaN(d.getTime())) {
    const parsed = Date.parse(dobString);
    if (!isNaN(parsed)) d = new Date(parsed);
  }

  if (isNaN(d.getTime())) {
    console.log('Compute Age node - failed to parse DOB:', dobString);
    return null;
  }

  const now = new Date();
  let age = now.getFullYear() - d.getFullYear();
  const m = now.getMonth() - d.getMonth();
  if (m < 0 || (m === 0 && now.getDate() < d.getDate())) age--;
  console.log('Compute Age node - parsed DOB:', d.toISOString(), 'computedAge:', age);
  return age;
}

const age = computeAge(canonical.dob);
const ageConfirmed = age !== null ? age >= 18 : null;

console.log('Compute Age node - age:', age, 'ageConfirmed:', ageConfirmed);

// Attach back to item.json.metadata (preserve other metadata)
item.metadata = Object.assign({}, metadata, canonical, { age, ageConfirmed });

return [{ json: item }];
